CREATE TABLE IF NOT EXISTS worlds(id TEXT PRIMARY KEY, snapshot TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS commands(world_id TEXT NOT NULL, account_id TEXT NOT NULL, command_id TEXT NOT NULL, PRIMARY KEY(world_id,account_id,command_id));
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, username TEXT UNIQUE COLLATE NOCASE NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(account_id TEXT PRIMARY KEY REFERENCES accounts(id), world_id TEXT NOT NULL REFERENCES worlds(id));
CREATE TABLE IF NOT EXISTS invites(token TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), expires INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
PRAGMA user_version=1;
